// Floor layouts and dining tables (schema v2, ported from legacy floor-domain.js
// and public/floor-shared.js). Geometry helpers are shared by the API (save
// validation) and the web (Floor Studio, reservation maps) so both agree.
// Owner: Agent B1 (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
import { z } from 'zod';
import { idempotencyKey } from './common';

export const floorContractsVersion = 2 as const;

/** Legacy schema-v2 canvas (layout units, not architectural dimensions). */
export const FLOOR_DEFAULT_WIDTH = 1200;
export const FLOOR_DEFAULT_HEIGHT = 800;
export const FLOOR_LIMITS = { tables: 150, objects: 300, zones: 50 } as const;

/** The 13 legacy reservation feature tags (`floor-model.js` tableFeatures). */
export const TABLE_FEATURES = [
  'Smoking', 'Non-smoking', 'Window side', 'Quiet area', 'Terrace', 'Near entrance', 'Far from entrance',
  'Center', 'Outdoor', 'Booth', 'Accessible', 'High chair compatible', 'Near bar',
] as const;
export type TableFeature = (typeof TABLE_FEATURES)[number];

export const TABLE_SHAPES = ['square', 'round', 'rect', 'booth', 'bar'] as const;
export type TableShape = (typeof TABLE_SHAPES)[number];

export const FLOOR_OBJECT_TYPES = ['wall', 'door', 'window', 'counter', 'text', 'chair', 'plant', 'divider', 'entrance', 'kitchen', 'bar'] as const;
export type FloorObjectType = (typeof FLOOR_OBJECT_TYPES)[number];

export const TABLE_STATUSES = ['available', 'occupied', 'reserved', 'cleaning', 'out_of_service'] as const;
export type TableStatus = (typeof TABLE_STATUSES)[number];

const num = z.number().finite();
const objectId = z.string().min(1).max(100).regex(/^[\w-]+$/, 'letters, digits, _ and - only');

export const floorZone = z.object({
  id: objectId,
  type: z.literal('zone'),
  label: z.string().trim().min(1).max(80),
  x: num, y: num, width: num, height: num, rotation: num.default(0),
  color: z.string().regex(/^#[0-9a-f]{6}$/i),
  locked: z.boolean().optional(),
  hidden: z.boolean().optional(),
});
export type FloorZone = z.infer<typeof floorZone>;

export const floorObject = z.object({
  id: objectId,
  type: z.enum(FLOOR_OBJECT_TYPES),
  label: z.string().trim().min(1).max(80),
  x: num, y: num, width: num, height: num, rotation: num.default(0),
  color: z.string().regex(/^#[0-9a-f]{6}$/i).optional(),
  locked: z.boolean().optional(),
  hidden: z.boolean().optional(),
  material: z.enum(['wood', 'stone', 'garden']).optional(),
});
export type FloorObject = z.infer<typeof floorObject>;

/** Background image: PNG/JPEG data URL (legacy, ≤ 1,000,000 chars) or an https URL. */
export const floorBackground = z.object({
  image: z.string().max(1_000_000).nullable().default(null),
  opacity: z.number().min(0).max(1).default(0.45),
  locked: z.boolean().default(true),
  x: num.min(0).default(0),
  y: num.min(0).default(0),
  width: num.positive().default(FLOOR_DEFAULT_WIDTH),
  height: num.positive().default(FLOOR_DEFAULT_HEIGHT),
});
export type FloorBackground = z.infer<typeof floorBackground>;

export const floorTableInput = z.object({
  /** Omit (or use a client-side "new-…" id) to create a table; the server issues the id and QR token. */
  id: z.string().min(1).max(100).optional(),
  label: z.string().trim().min(1).max(20),
  capacity: z.number().int().min(1).max(50),
  /** Optional: a new branch has no zones yet (DB column is nullable). Blank → null. */
  zone: z.string().trim().max(40).nullable().optional().transform((v) => (v ? v : null)),
  shape: z.enum([...TABLE_SHAPES, 'rectangle']).transform((s) => (s === 'rectangle' ? 'rect' : s) as TableShape),
  cx: num, cy: num,
  width: num.min(40).max(500),
  height: num.min(40).max(500),
  rotation: num.default(0),
  features: z.array(z.enum(TABLE_FEATURES)).max(TABLE_FEATURES.length).optional(),
  reservable: z.boolean().optional(),
  minSpendMinor: z.number().int().min(0).max(100_000_000).nullable().optional(),
  premium: z.boolean().optional(),
  internalNotes: z.string().max(5000).nullable().optional(),
});
export type FloorTableInput = z.infer<typeof floorTableInput>;

export const floorSaveInput = z.object({
  baseRevision: z.number().int().min(0),
  key: idempotencyKey,
  layout: z.object({
    width: z.number().int().min(200).max(10000).default(FLOOR_DEFAULT_WIDTH),
    height: z.number().int().min(200).max(10000).default(FLOOR_DEFAULT_HEIGHT),
    background: floorBackground.default({ image: null, opacity: 0.45, locked: true, x: 0, y: 0, width: FLOOR_DEFAULT_WIDTH, height: FLOOR_DEFAULT_HEIGHT }),
    zones: z.array(floorZone).max(FLOOR_LIMITS.zones),
    objects: z.array(floorObject).max(FLOOR_LIMITS.objects),
    tables: z.array(floorTableInput).max(FLOOR_LIMITS.tables),
  }),
});
export type FloorSaveInput = z.infer<typeof floorSaveInput>;

export interface FloorTable {
  id: string;
  label: string;
  capacity: number;
  zone: string | null;
  shape: TableShape;
  cx: number; cy: number; width: number; height: number; rotation: number;
  features: string[];
  reservable: boolean;
  minSpendMinor: number | null;
  premium: boolean;
  internalNotes: string | null;
  status: TableStatus;
  version: number;
}

export interface FloorLayout {
  branchId: string;
  revision: number;
  schemaVersion: 2;
  width: number;
  height: number;
  background: FloorBackground;
  zones: FloorZone[];
  objects: FloorObject[];
  tables: FloorTable[];
  /** Present on PUT responses: client draft id → server table id for created tables. */
  created?: Array<{ clientId: string | null; id: string }>;
}

export interface LiveFloorTable extends FloorTable {
  visit: null | {
    id: string; partySize: number | null; openedAt: string; orderCount: number; dueMinor: number; paidMinor: number; requests: string[];
    /** Orders still in the kitchen (placed/accepted/preparing) and ready to serve: the legacy "In the kitchen" / "Food ready". */
    preparing?: number; ready?: number; totalMinor?: number;
    openedVia?: string;
    /** Opened by a guest scan less than a minute ago with no activity: "Release table" is still possible. */
    undoable?: boolean;
    billingLocked?: boolean;
  };
  nextReservation: null | { id: string; startsAt: string; guestName: string; partySize: number };
}
export interface LiveFloor { revision: number; tables: LiveFloorTable[] }

export interface PublicFloorTable {
  id: string; label: string; capacity: number; zone: string | null; shape: TableShape;
  cx: number; cy: number; width: number; height: number; rotation: number;
  features: string[]; reservable: boolean; minSpendMinor: number | null; premium: boolean;
}
export interface PublicFloor {
  branchId: string; branchCode: string; revision: number; width: number; height: number;
  background: FloorBackground; zones: FloorZone[]; objects: FloorObject[]; tables: PublicFloorTable[];
}

export interface QrSheetItem { tableId: string; label: string; url: string; svg: string }

// ---------------------------------------------------------------------------
// Geometry (port of legacy floor-shared.js `bounds` / `geometryError` / `overlaps`)
// ---------------------------------------------------------------------------
export interface Geometry { x?: number; y?: number; cx?: number; cy?: number; width: number; height: number; rotation?: number; label?: string }

/** Axis-aligned bounds of a (possibly rotated) rectangle centred on (cx|x, cy|y). */
export function bounds(o: Geometry) {
  const x = o.cx ?? o.x ?? 0;
  const y = o.cy ?? o.y ?? 0;
  const r = ((o.rotation || 0) * Math.PI) / 180;
  const w = Math.abs(Math.cos(r)) * o.width + Math.abs(Math.sin(r)) * o.height;
  const h = Math.abs(Math.sin(r)) * o.width + Math.abs(Math.cos(r)) * o.height;
  return { left: x - w / 2, right: x + w / 2, top: y - h / 2, bottom: y + h / 2 };
}

/** Returns a human-readable problem with an object's geometry, or null when it fits the canvas. */
export function geometryError(o: Geometry, f: { width: number; height: number } = { width: FLOOR_DEFAULT_WIDTH, height: FLOOR_DEFAULT_HEIGHT }): string | null {
  const values = [o.cx ?? o.x, o.cy ?? o.y, o.width, o.height, o.rotation ?? 0];
  if (!values.every((v) => typeof v === 'number' && Number.isFinite(v)) || o.width < 4 || o.height < 4 || (o.rotation ?? 0) < 0 || (o.rotation ?? 0) >= 360) {
    return 'Use valid dimensions and a rotation between 0 and 359.';
  }
  const b = bounds(o);
  if (b.left < 0 || b.top < 0 || b.right > f.width || b.bottom > f.height) return 'Object is outside the canvas.';
  return null;
}

/** Pairs of overlapping tables/counters (advisory warning in the editor; never blocks a save). */
export function overlaps(items: Geometry[]): string[] {
  const pairs: string[] = [];
  for (let i = 0; i < items.length; i++) {
    for (let j = i + 1; j < items.length; j++) {
      const a = bounds(items[i]!), b = bounds(items[j]!);
      if (a.left < b.right && a.right > b.left && a.top < b.bottom && a.bottom > b.top) pairs.push(`${items[i]!.label ?? i} / ${items[j]!.label ?? j}`);
    }
  }
  return pairs;
}
